import HeroStats from './HeroStats';
import {
  HeroSection,
  ArrowIcon,
  HeroContainer,
  GetStartedBtn,
  StatsContainer,
  ArrowIconWrapper,
  HeroTitle,
  HeroText,
} from './Hero.styled';
import { useNavigate } from 'react-router-dom';

function Hero() {
  const navigate = useNavigate();

  function handleGetStartedClick() {
    navigate('/nannies');
  }

  return (
    <HeroSection>
      <HeroContainer>
        <HeroTitle>Make Life Easier for the Family:</HeroTitle>
        <HeroText>Find Babysitters Online for All Occasions</HeroText>
        <GetStartedBtn
          type="button"
          $paddingX={46}
          $paddingY={18}
          onClick={handleGetStartedClick}
        >
          Get started
          <ArrowIconWrapper>
            <ArrowIcon icon="ci:arrow-up-right-lg" className="default-icon" />
            <ArrowIcon icon="ci:arrow-right-lg" className="hover-icon" />
          </ArrowIconWrapper>
        </GetStartedBtn>
      </HeroContainer>
      <StatsContainer>
        <HeroStats />
      </StatsContainer>
    </HeroSection>
  );
}

export default Hero;
